  "plans.eyebrow": "Тарифы и функции",
  "plans.title": "Сравнить тарифы StockHaven",
  "plans.intro": "Один аккаунт при любом выбранном тарифе — Business охватывает до пяти бизнесов. Цены указаны в долларах США за месяц, и новые клиенты сайта, имеющие право на пробный период, могут получить один семидневный пробный период для Essentials и Business. Переход с существующей подписки Essentials на Business не перезапускает пробный период и не создаёт ещё один бесплатный пробный период. Цены тарифов для сайта указаны без применимых налогов, если таковые имеются. Точная сумма списания будет показана до того, как вы авторизуете подписку.",
