  "plans.mobileIncludedNote": "Оба тарифа для сайта включают мобильное приложение-компаньон, поэтому подписчик сайта никогда не платит также ежемесячную плату за мобильную версию.",
  "plans.priceNote": "Essentials стоит $14.99/месяц плюс применимые налоги, если таковые имеются. Business стоит $29.99/месяц плюс применимые налоги, если таковые имеются. Любой требуемый налог определяется при оплате у провайдера и должен быть указан в итоговой сумме перед оплатой. Эта страница сравнения не является расчётом налога или разрешением на оплату.",
  "plans.mobilePriceNote": "Тариф только для мобильных устройств стоит $4.99/месяц по запланированной базовой цене для США. App Store или Google Play показывает фактическую локальную цену подписки и применимые налоги перед покупкой. Лимиты по товарам, объектам и сотрудникам для этого тарифа устанавливаются при запуске, отдельно от тарифов для сайта.",
  "plans.planChangeNote": "Изменение тарифа для сайта должно быть подтверждено платёжным провайдером. Новая цена, дата вступления в силу и любой пропорциональный перерасчёт будут разъяснены до авторизации изменения. Переход на более высокий тариф не должен создавать вторую подписку.",
  "plans.providerNote": "Цены, списания и пробные периоды обрабатываются провайдером, через которого вы оформляете подписку, — App Store, Google Play, сайт или Shopify, — а не этой страницей.",
