  "upgrade.pendingCheckoutIntro": "Это новое рабочее пространство ограничено тарифом Essentials, пока вы не выберете подписку. Новые клиенты, имеющие право на пробный период, могут получить один пробный период продолжительностью {days} дн. на аккаунт.",
