  "upgrade.upgradeNeverRestartsTrial": "Переход на более высокий тариф никогда не перезапускает ваш бесплатный пробный период.",
  "upgrade.trialHistoryNote": "Если вы платите за Essentials и переходите на Business, вы сохраняете тот же клиентский аккаунт и историю пробных периодов. Business не включает дополнительный семидневный пробный период. Если вы переходите на более высокий тариф, пока ваш первоначальный пробный период ещё действует, его первоначальная дата окончания не сбрасывается.",
  "upgrade.providerConfirmNote": "Изменения тарифа требуют подтверждения от платёжного провайдера. Любая разница в цене, пропорциональный перерасчёт и дата вступления в силу должны быть показаны до того, как вы одобрите изменение. Переход на более высокий тариф не должен создавать вторую одновременную подписку.",
  "upgrade.chargedThroughProviderNote": "Изменения тарифа оплачиваются через платёжного провайдера. Вы можете отменить подписку на этой странице с помощью кнопки отмены подписки под вашим текущим тарифом или в разделе настроек. Отмена прекращает будущие продления в конце вашего оплаченного периода; она никогда не прекращает ваш доступ сразу. Существующие бесплатные рабочие пространства не оплачиваются за просмотр этих параметров.",
  "billing.cancel.title": "Отменить подписку",
  "billing.cancel.description": "Отписаться от {plan}. Отмена прекращает будущие продления в конце вашего оплаченного периода — она никогда не прекращает ваш доступ сразу.",
  "billing.cancel.yourPlan": "ваш тариф",
  "billing.cancel.doneTitle": "Ваша подписка отменена.",
  "billing.cancel.doneWithEnd": "Вы сохраняете полный доступ до {endDate}. После этой даты у вас есть льготный период только для чтения продолжительностью {graceDays} дн. — вы по-прежнему можете войти и видеть свои товары, но не можете ничего добавлять, редактировать, удалять, сканировать, импортировать, экспортировать или изменять. {gracePart}",
  "billing.cancel.graceEndsOn": "После того как 15-дневный льготный период закончится {date}, ваш аккаунт и вся его информация будут безвозвратно удалены и не смогут быть восстановлены.",
  "billing.cancel.doneNoEnd": "Вы сохраняете полный доступ до конца вашего оплаченного периода. После этого применяется 15-дневный льготный период только для чтения. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Вы отменили подписку в течение 3 дней с момента первого платного списания, поэтому вы можете иметь право на возврат этого первого платежа. Сама отмена не осуществляет возврат — запросите его через {contact}.",
  "billing.cancel.refundWindowClosed": "Сама по себе отмена не осуществляет возврат средств. Возвраты применяются только в течение 3 дней с момента первого успешного платного списания, по запросу через {contact}.",
