  "billing.cancel.alreadyCanceledNoEnd": "Она заканчивается в конце текущего оплаченного периода. До этого момента вы сохраняете полный доступ.",
  "billing.cancel.appStoreNote": "Если вы когда-либо оформите подписку через Google Play или Apple App Store, вам может потребоваться отменить её через настройки подписок этого магазина. Это диалоговое окно не может остановить выставление счетов в магазине приложений. Удаление приложения или удаление вашего аккаунта StockHaven не отменяет подписку в магазине.",
  "billing.cancel.trialNote": "Отмена во время пробного периода сохраняет ваши полные 7 дней — доступ заканчивается {date}, и с вас ничего не будет списано.",
