  "exports.eyebrow": "Данные",
  "exports.title": "Экспорт и резервные копии",
  "exports.subtitleStart": "Загрузки всегда ограничены",
  "exports.subtitleRest": ". Каждый файл помечен названием компании и датой его создания.",
  "exports.createBusinessFirst": "Сначала создайте компанию — экспорт относится к компании, а не к приложению.",
  "exports.lockedTitle": "Экспорт в CSV и Excel — функция тарифа Business",
  "exports.lockedDesc": "Ваше рабочее пространство на тарифе Essentials. Business добавляет экспорт в CSV и Excel, оценку стоимости остатков, неограниченное количество товаров и сотрудников, поставщиков, закупки и комплекты.",
  "exports.seeBusiness": "Посмотреть, что входит в Business",
  "exports.whatTheseAre": "Что представляют собой эти файлы",
  "exports.about1": "Каждый набор данных доступен в формате CSV или настоящей книги Excel (.xlsx) — полная книга остатков доступна только в Excel, по одному листу на набор данных. Файлы CSV открываются в Excel, Numbers, Google Sheets и большинстве приложений для учёта остатков. Текст в UTF-8, запятые в кавычках, переносы строк в заметках и ведущие нули в кодах сохраняются, а ячейки, начинающиеся как формула, нейтрализуются, чтобы электронная таблица открывала их как текст.",
  "exports.about2": "В файлах Excel значения SKU, UPC, ISBN и штрих-коды являются текстовыми ячейками — никогда не отображаются в экспоненциальной записи и никогда не теряют нули — с применёнными шириной столбцов, фильтрами заголовков и форматами валюты или количества. Полная книга остатков хранит товары, уровни остатков, местоположения и перемещения на отдельных листах.",
  "exports.about3": "Очень большие объёмы экспорта останавливаются на отметке 20000 строк на набор данных — когда это происходит, имя файла говорит об этом (truncated-20000), поэтому неполный файл никогда не будет принят за полный.",
  "exports.about4": "Резервная копия — это снимок ваших данных, а не восстановление в один клик. Её восстановление — ручная работа с предварительным просмотром, поэтому храните файл в надёжном месте — пока ничто в приложении не может воссоздать удалённую компанию из неё. Код приложения и резервные копии платформы Base44 обрабатываются отдельно от этих файлов.",
  "exports.about5": "Фотографии и вложения перечислены в виде сохранённых ссылок — сами файлы изображений не упаковываются в загрузку.",
  "exports.backupTitle": "Полная резервная копия",
  "exports.backupDesc": "Один файл с товарами этой компании, местоположениями, уровнями остатков, полным журналом перемещений, поставщиками, закупками, заказами, возвратами, подсчётами и объявлениями — а также настройками её профиля. Храните его там, где вы можете его контролировать.",
  "exports.backupIncludes1": "Товары, коды, затраты и заметки",
  "exports.backupIncludes2": "Местоположения и количество по каждому местоположению",
  "exports.backupIncludes3": "Каждое перемещение, с указанием исполнителя и времени",
