  "import.eyebrow": "Данные",
  "import.title": "Центр импорта",
  "import.subtitleStart": "Три отдельные операции с электронными таблицами, чтобы исправление цены никогда не поступило как приёмка остатков. Всё попадает только в",
  "import.subtitleRest": ", и ничего не записывается, пока не будет пройдена пробная проверка.",
  "import.createBusinessFirst": "Сначала создайте компанию — импортированные товары относятся к компании.",
  "import.createBusinessFirstShort": "Сначала создайте компанию.",
  "import.whatEachDoes": "Что делает каждая операция",
  "import.createTitle": "Создать новые товары",
  "import.createDesc": "добавляет строки, которых ещё нет в каталоге. Дублирующиеся SKU и штрих-коды, уже используемые, пропускаются, а начальные остатки могут поступить в выбранное вами местоположение как приёмка.",
  "import.updateTitle": "Обновить существующие товары",
  "import.updateDesc": "сопоставляет каждую строку по SKU или ID записи и показывает старое значение рядом с предлагаемым новым. Пустые ячейки оставляют сохранённое значение без изменений, если вы не попросите очистить пустые поля, а количество никогда не затрагивается.",
  "import.receiveModeTitle": "Принять остатки",
  "import.receiveModeDesc": "добавляет поступающее количество в одно местоположение и записывает приёмку в журнал перемещений для каждой строки. Каждая партия помечается, поэтому один и тот же лист нельзя принять дважды.",
  "import.excelNote": "Книги Excel (.xlsx) читаются напрямую — выберите лист, и столбцы будут сопоставлены за вас. Коды остаются целыми: UPC, сохранённый как текст, сохраняет свои цифры и ведущие нули. Строки, которые нельзя импортировать, перечислены с указанием причины",
