  "print.nothingToPrint": "Пока нечего печатать",
  "print.pickOrderHint": "Выберите заказ на закупку из списка, чтобы просмотреть документ.",
  "print.pickCustomerOrderHint": "Выберите заказ клиента из списка, чтобы просмотреть документ.",
  "print.pickReturnHint": "Выберите зарегистрированный возврат из списка, чтобы просмотреть документ.",
  "print.chooseStyleHint": "Выберите стиль, затем выберите товары из списка. Предварительный просмотр показывает точно то, что выйдет из принтера.",
  "print.howToReach": "Как подключиться к вашему принтеру",
  "print.howIntro": "Это приложение подключается к принтерам, которые у вас уже есть, — само оно принтером не является. Есть четыре способа подключиться к одному из них, и ценники печатаются на обоих тарифах любым из них. Упаковочные листы, заказы на закупку, документы поставщиков и отчёты доступны только в Business, независимо от подключения.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "С этой страницы, в Chrome или Edge на компьютере и в Chrome на Android: выберите ваш принтер ценников, и ценники отправятся прямо на него. Это не работает в Safari на iOS — на iPhone печать по Bluetooth доступна в мобильном приложении. Принтер, который понимает только Zebra ZPL или собственный язык Brother, не поймёт ценники, которые отправляет эта страница; это проверяется на реальных принтерах, прежде чем будет названо работающим.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Подключите принтер к Wi-Fi вашего магазина, затем используйте кнопку «Печать» — печать выполняется через принтер, установленный на этом компьютере, по сети магазина. На iPhone AirPrint встроен: принтер AirPrint в той же сети Wi-Fi просто появляется в листе печати, без шнура и без приложения, и приложению не нужен код, специфичный для AirPrint. Принтер должен поддерживать AirPrint (большинство новых поддерживает), а телефон и принтер должны быть в одной сети Wi-Fi.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Подключите принтер к сети вашего магазина шнуром Ethernet, установите его на компьютере и печатайте через кнопку «Печать». Ethernet — это путь для компьютеров — iPhone не используют шнуры Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Подключите принтер к компьютеру его шнуром и используйте кнопку «Печать» — печать выполняется через установленный там принтер. На телефоне Android с кабелем USB OTG кнопка USB выше напрямую обращается к принтеру. iPhone не могут печатать по USB напрямую — там нет WebUSB — поэтому используйте Wi-Fi / AirPrint или Bluetooth из мобильного приложения.",
  "print.howCordsLead": "Шнуры по-прежнему служат iPhone, на один шаг удалённо.",
  "print.howCordsBody": "Принтер USB, подключённый к компьютеру магазина, или принтер Ethernet, подключённый к сети, появляется на вашем iPhone по Wi-Fi магазина (AirPrint / общий принтер) — шнуры надёжно подключают принтер к сети, а телефон обращается к нему по беспроводной связи.",
  "print.howOfflineLead": "Если интернет пропадёт,",
  "print.howOfflineBody": "ценники и документы, уже находящиеся на этой странице, по-прежнему печатаются — кнопка «Печать», PDF с ценниками, Bluetooth и USB не нуждаются в подключении. Что действительно нуждается в интернете — это загрузка страницы и её товаров в первую очередь. Полный автономный режим (работа в приложении вообще без подключения) — это отдельная, более крупная разработка, и здесь он не заявляется.",
