  "settings.cancelTerms.intro": "Это условия для платных подписок Luminous StockHaven. Оплата подписки на сайте осуществляется через Stripe. Вы можете отменить подписку самостоятельно в любое время с помощью кнопки «Отменить подписку» ниже — одобрение сотрудников не требуется. Запросы на отмену и возврат также можно направить через официальную службу поддержки по адресу theluminousbookshop@outlook.com.",
  "settings.cancelTerms.noApprovalBody": "Вы можете отменить подписку самостоятельно в любое время. Одобрение сотрудников не требуется. Будущие продления прекращаются только после того, как платёжный провайдер подтвердит отмену.",
  "settings.cancelTerms.noApprovalTitle": "Отмена без одобрения:",
  "settings.cancelTerms.paymentBody": "Для платных пробных периодов семидневный пробный период требует способ оплаты при регистрации. Если подписка не отменена в применимый срок отмены пробного периода, выбранный ежемесячный тариф будет оплачен автоматически после пробного периода. Цена, дата первого списания и срок отмены у конкретного провайдера должны быть показаны при регистрации. Оплата пробного периода осуществляется через Stripe.",
  "settings.cancelTerms.paymentTitle": "Способ оплаты и автоматическое продление:",
  "settings.cancelTerms.remainingBody": "Если вы уже оплатили период оплаты, вы можете сохранять доступ до подтверждённой даты, до которой произведена оплата. Более раннее прекращение требует соответствующего подтверждения провайдера и обработки возможного возврата. Доступ в бесплатном пробном периоде заканчивается в соответствии с подтверждённой провайдером датой окончания пробного периода.",
  "settings.cancelTerms.remainingTitle": "Оставшийся доступ:",
  "settings.cancelTerms.storesBody": "Если вы когда-либо оформите подписку через Google Play или Apple App Store, ваша подписка будет оплачиваться и управляться этим магазином. Возможно, вам потребуется отменить её непосредственно в разделе подписок того же аккаунта Google или Apple, который использовался для подписки. Отмена отдельной подписки на сайте, удаление этого приложения или запрос на удаление аккаунта Luminous StockHaven не отменяют автоматически подписку, оплачиваемую через магазин. Проверьте чек о покупке, чтобы подтвердить, кто выставляет вам счета.",
  "settings.cancelTerms.storesTitle": "Подписки Google Play и Apple App Store (если вы когда-либо оформите подписку через магазин):",
  "settings.cancelTerms.title": "Условия и положения отмены",
  "settings.cancelTerms.trialBody": "Семидневный пробный период можно использовать только один раз на одного правомочного клиента. Отмена пробного периода или подписки не даёт права на ещё один пробный период; возвращающиеся клиенты должны выбрать платную подписку.",
  "settings.cancelTerms.trialTitle": "Один бесплатный пробный период:",
  "settings.canceled.endsOn": "Эта подписка отменена и заканчивается {date}. До этого момента у вас сохраняется полный доступ.",
  "settings.delete.checking": "Проверка существующего запроса на удаление…",
  "settings.delete.description": "Запросить удаление вашего аккаунта для входа в Luminous StockHaven.",
  "settings.delete.dialogDescription": "При этом запрашивается проверка удаления аккаунта. Это не удаляет сразу ваш вход или остатки и не отменяет подписку Stripe. Введите {word}, чтобы подтвердить, что вы хотите отправить запрос.",
  "settings.delete.dialogTitle": "Запросить удаление аккаунта",
  "settings.delete.enterDelete": "Введите {word} для подтверждения",
  "settings.delete.exportFirst": "Сначала экспортируйте ваши остатки, если вам нужно сохранить записи.",
  "settings.delete.intro": "Отправка запроса не удаляет сразу ваш аккаунт, компании или остатки. Запросы рассматриваются отдельно, прежде чем удаление может быть завершено. Этот запрос не отменяет подписку Stripe и не останавливает будущие списания; отмена подписки должна выполняться отдельно через платёжного провайдера.",
  "settings.delete.keepAccount": "Сохранить аккаунт",
  "settings.delete.noExport": "В тарифе Essentials нет экспорта — запишите всё необходимое перед запросом на удаление.",
