  "settings.pastDue.body": "Ваш последний платёж не прошёл. Обновите способ оплаты на странице повышения тарифа — Stripe повторит попытку по собственному расписанию, и ваша подписка не будет отменена досрочно. Если вы не уверены, что делать, обратитесь в службу поддержки по адресу theluminousbookshop@outlook.com.",
