  "settings.separateDecisions": "Отмена подписки и удаление аккаунта — это отдельные решения. Ни одна подписка не будет отменена и ни один аккаунт не будет удалён при просмотре этих условий.",
  "settings.software.application": "Приложение",
  "settings.software.description": "Luminous StockHaven — это приложение. Данные вашей компании в других местах на этой странице принадлежат вам.",
  "settings.software.fixedNote": "Эти значения фиксированы и отображаются одинаково для каждой компании. Переименование вашей компании или изменение её логотипа никогда не меняет название приложения.",
