  "settings.switcher.taglinePlaceholder": "Необязательно",
  "settings.switcher.upgrade": "Повысить тариф",
  "settings.title": "Настройки",
  "settings.trial.cancelKeeps": "Отмена во время пробного периода сохраняет ваши полные 7 дней — доступ заканчивается {date}, и с вас не будет списания.",
  "staff.access.noSeatBody": "У вашего аккаунта нет места сотрудника для этой компании, поэтому её остатки остаются закрытыми. Попросите владельца добавить вас в разделе «Сотрудники и роли».",
  "staff.access.noSeatTitle": "Эта компания не открыта для вашего входа",
  "staff.access.pendingBody": "У этой компании есть приглашение для вашей электронной почты, которое ещё не активировано. Попросите владельца установить статус вашего сотрудника как активный. До этого момента здесь ничего не видно.",
  "staff.access.pendingTitle": "Ваше приглашение ещё не активно",
  "staff.access.signOut": "Выйти",
  "staff.access.suspendedBody": "Администратор приостановил этот аккаунт сотрудника для активной компании. Попросите его снова установить вас как активного, затем войдите снова.",
  "staff.access.suspendedTitle": "Ваш доступ приостановлен",
  "staff.addFirst": "Добавить первого сотрудника",
  "staff.addMember": "Добавить сотрудника",
  "staff.emptyBody": "Добавьте человека, дайте ему роль и разрешения, которые с ней идут, и он будет приглашён по электронной почте для входа в эту компанию.",
  "staff.emptyTitle": "Сотрудников пока нет",
  "staff.eyebrow": "Команда",
  "staff.how.p1": "У каждого участника есть роль и собственный список разрешений, поэтому вы можете начать с роли и изменить одно, не создавая новую роль. Редактирование роли не переписывает участников, уже находящихся на ней — откройте участника, чтобы повторно применить значения его роли по умолчанию.",
  "staff.how.p2": "Пользовательские роли — функция тарифа Business: Essentials использует пять встроенных ролей (Owner, Manager, Stock clerk, Sales clerk, Viewer).",
  "staff.how.p3": "Приглашения отправляются по электронной почте. Участник может войти только после принятия, а удаление кого-либо из этого списка не удаляет его аккаунт в приложении.",
  "staff.how.p4": "Магазин — это локация, к которой назначен человек. Она записывается на его карточке; то, что он может открыть, по-прежнему определяется его ролью и разрешениями.",
  "staff.how.p5": "Разрешения определяют, что каждый человек может открыть: пункты меню вне его роли скрыты, а заблокированный адрес показывает уведомление «не в вашей роли» вместо страницы. Изменение применяется при следующей загрузке приложения этим человеком; приостановка участника полностью блокирует его.",
  "staff.how.p6": "Администраторы могут видеть и изменять все данные, управлять пользователями приложения и ролями и никогда не ограничиваются ролью сотрудника. Тот, у кого нет записи сотрудника — владелец новой компании — сохраняет полный доступ.",
  "staff.howTitle": "Как работают сотрудники и роли",
  "staff.limitBadgeLabel": "Сотрудники",
  "staff.loading": "Загрузка сотрудников…",
