  "rewards.subtitle": "Скажите спасибо наградой — процентом скидки, подарочной картой или чем угодно, что вы опишете.",
  "rewards.title": "Награды и стимулы",
  "rewards.value.giftCard": "Подарочная карта на {value}",
  "rewards.value.percentOff": "Скидка {percent}% в магазине",
  "rewards.void": "Аннулировать",
  "rewards.voided": "Награда аннулирована.",
  "workforce.tab.rewards": "Награды",
  "training.lessons.mgr-give-rewards.step1": "Откройте «Команда» и нажмите «Награды». Выберите члена команды, затем вид: процент скидки в магазине, подарочная карта или что-то другое, что вы опишете своими словами.",
  "training.lessons.mgr-give-rewards.step2": "Дайте награде короткое название и заметку, если хотите. Человек сразу получает сигнал, а награда ждёт в его «Моих наградах» со своим собственным кодом.",
  "training.lessons.mgr-give-rewards.step3": "Граница, по замыслу: вы награждаете только СОТРУДНИКОВ. Вы не можете наградить себя или другого менеджера — награждение менеджера — это решение владельца, и приложение честно откажет в этом.",
  "training.lessons.mgr-give-rewards.step4": "На кассе введите код, который показывает вам член команды, и отметьте его как использованный — каждый код работает один раз. Вы можете аннулировать вручённую вами награду, если планы изменятся; подарки владельца — это владельцу аннулировать.",
  "training.lessons.mgr-give-rewards.title": "Вручение наград вашим сотрудникам",
  "training.lessons.owner-give-rewards.step1": "Награды находятся в «Команде», на вкладке «Награды», и они доступны только на тарифе Business — на Essentials вкладка показывает запертую дверь, чтобы ваша команда могла видеть, что предлагает больший тариф.",
  "training.lessons.owner-give-rewards.step2": "Вы можете наградить ЛЮБОГО в команде — и сотрудников, и менеджеров. Выберите человека, затем вид: процент скидки в магазине (любой процент на ваш выбор), подарочная карта куда угодно или любой стимул, который вы опишете своими словами.",
  "training.lessons.owner-give-rewards.step3": "Награда поступает со своим собственным одноразовым кодом и звонит в колокольчик человека. Они показывают код на кассе; владелец или менеджер вводит его, чтобы отметить как использованный.",
  "training.lessons.owner-give-rewards.step4": "Печатная или переданная квитанция о награде содержит только название ВАШЕГО бизнеса — никогда название приложения. Это благодарность вашего магазина, а не реклама.",
  "training.lessons.owner-give-rewards.title": "Вручение наград (тариф Business)",
  "training.lessons.owner-rewards-oversight.step1": "Ваш менеджер тоже может вручать награды — только сотрудникам. Приложение отказывает менеджеру, награждающему себя или другого менеджера; награждение менеджера — всегда ваше решение.",
  "training.lessons.owner-rewards-oversight.step2": "Вы видите каждую награду в бизнесе в истории наград: кто её вручил, кто её получил и готова ли она, использована или аннулирована. Менеджер видит только награды, которые он вручил, и те, которые он получил.",
  "training.lessons.owner-rewards-oversight.step3": "Вы можете аннулировать любую награду, включая ту, которую вручил ваш менеджер. Менеджер может аннулировать свои подарки, но никогда ваши.",
  "training.lessons.owner-rewards-oversight.step4": "Каждый код работает ровно один раз, а аннулированная награда никогда не может быть использована — история всегда показывает, чем закончилась награда.",
  "training.lessons.owner-rewards-oversight.title": "Надзор за наградами: вручения вашего менеджера",
  "training.lessons.staff-your-rewards.step1": "Когда ваш менеджер или владелец вручает вам награду, ваш колокольчик звонит. Откройте «Команда» и нажмите «Награды», чтобы увидеть её в «Моих наградах».",
  "training.lessons.staff-your-rewards.step2": "У каждой награды есть свой собственный код. Держите его при себе — тот, кто показывает код на кассе, и использует награду.",
  "training.lessons.staff-your-rewards.step3": "Чтобы использовать её, покажите код при покупке. Человек на кассе вводит его и отмечает как использованный — каждый код работает ровно один раз.",
  "training.lessons.staff-your-rewards.step4": "Награды — это удовольствие тарифа Business. Если ваш магазин не на Business, вкладка «Награды» вместо этого показывает запертую дверь — это тариф, а не ошибка.",
  "training.lessons.staff-your-rewards.title": "Ваши награды: как найти свой код и использовать его",
  "training.module.rewards": "Награды и стимулы",
